def snake_case(s: str) -> str:
    result = []
    for i, char in enumerate(s):
        if char.isupper() and i != 0:
            result.append('_')
        result.append(char.lower())
    return ''.join(result)

def initials(s: str) -> str:
    words = s.split()
    return ''.join(word[0] for word in words).upper()

def mask_secret(s: str) -> str:
    """
    Replace every character except the last four with '*'.
    Inputs of four or fewer characters are entirely masked.
    """
    if len(s) <= 4:
        return '*' * len(s)
    return '*' * (len(s) - 4) + s[-4:]

import re

def filename_safe(s: str) -> str:
    """Replace every character that is not a letter, digit, dot, underscore or hyphen with an underscore."""
    return re.sub(r'[^a-zA-Z0-9._-]', '_', s)

def cap_words(s: str) -> str:
    """Capitalize the first letter of every whitespace-separated word and lowercase the rest; single-space the words."""
    words = s.split()
    return ' '.join(word.capitalize() for word in words)

def reverse_words(s: str) -> str:
    """Return the words in reverse order, single-spaced."""
    words = s.split()
    return ' '.join(reversed(words))
